css:
body{margin:0;background:#070B1B}
*{box-sizing:border-box}
.apw{--bg:#FFFFFF;--bg2:#F6F4EF;--bg3:#E4EEF8;--card:#FFFFFF;--ink:#0E1430;--ink2:#3E4668;--mute:#4A5272;--line:#E2DDD2;--field:#8A91B0;--accent:#FF4A1C;--accent-hi:#FF6B42;--accent-ink:#0E1430;--accent-text:#B02A08;--accent-soft:#FFE1D6;--ok:#1E7A52;--ok-soft:#E3F1EA;--band:#0A0F24;--band2:#111936;--shadow:0 14px 34px rgba(10,15,36,.14);font-family:"Schibsted Grotesk",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
.apw.dark{--bg:#0A0F24;--bg2:#0E1530;--bg3:#101A38;--card:#141D3D;--ink:#F6F4EF;--ink2:#D5DAF0;--mute:#AEB5D8;--line:rgba(255,255,255,.13);--field:#6B7398;--accent-text:#FF8A66;--accent-soft:rgba(255,74,28,.16);--ok:#4CC38A;--ok-soft:rgba(76,195,138,.15);--band:#070B1B;--band2:#111936;--shadow:0 14px 34px rgba(0,0,0,.45)}
.apw a{color:var(--accent-text)}
.mono{font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace}
.wm{font-family:"Archivo","Arial Black",sans-serif;font-weight:800;text-transform:uppercase;letter-spacing:.045em;line-height:1}
.eb{margin:0;font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace;font-size:13px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;color:var(--accent-text)}
.h1{margin:0;font-weight:800;letter-spacing:-.05em;line-height:.95;text-wrap:balance}
.h2{margin:10px 0 0;font-size:34px;font-weight:800;letter-spacing:-.045em;line-height:1;text-wrap:balance}
.lead{margin:12px 0 0;font-size:17px;line-height:1.55;color:var(--ink2)}
.btn{display:flex;align-items:center;justify-content:center;gap:10px;min-height:56px;padding:0 24px;border-radius:999px;border:1.6px solid transparent;font:inherit;font-size:18px;font-weight:700;line-height:1;cursor:pointer;text-decoration:none;white-space:nowrap}
.btn:disabled{opacity:.45;cursor:not-allowed}
.apw .btn-dot{background:var(--accent);color:var(--accent-ink)}.apw .btn-dot:hover{background:var(--accent-hi);color:var(--accent-ink)}
.apw .btn-ink{background:var(--ink);color:var(--bg)}
.apw .btn-line{background:transparent;color:var(--ink);border-color:var(--field)}
.apw .btn-line-n{background:transparent;color:#FFFFFF;border-color:rgba(255,255,255,.3)}
.apw .btn-pay{background:#000000;color:#FFFFFF;border-color:#000000}
.apw.dark .btn-pay{border-color:rgba(255,255,255,.4)}
.ibtn{width:48px;height:48px;flex:0 0 48px;display:grid;place-items:center;border-radius:50%;border:1.6px solid var(--line);background:transparent;color:var(--ink);cursor:pointer;padding:0;text-decoration:none}
.apw .ibtn-n{border-color:rgba(255,255,255,.24);color:#F6F4EF}
.ldot{display:inline-block;width:9px;height:9px;flex:0 0 9px;border-radius:50%;background:#FF4A1C;animation:apwBlink 1.6s ease-out infinite}
details>summary{list-style:none;cursor:pointer}details>summary::-webkit-details-marker{display:none}
.chev{transition:transform .2s ease}details[open]>summary .chev{transform:rotate(45deg)}
@keyframes apwBlink{0%{box-shadow:0 0 0 0 rgba(255,74,28,.6)}70%{box-shadow:0 0 0 8px rgba(255,74,28,0)}100%{box-shadow:0 0 0 0 rgba(255,74,28,0)}}
@media (prefers-reduced-motion:reduce){.ldot{animation:none}}
input:focus-visible,button:focus-visible,a:focus-visible,summary:focus-visible,textarea:focus-visible,ul:focus-visible{outline:3px solid #FF6B42;outline-offset:2px}
.vsw{border-radius:22px;overflow:hidden;background:#0A0F24;box-shadow:var(--shadow)}
.vs{position:relative;overflow:hidden;background:#BFDDF3;aspect-ratio:4/3;isolation:isolate}
.vs>svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.dark .vs>svg{filter:brightness(.88) saturate(.95)}
.vs .chipv{position:absolute;top:10px;z-index:2;display:inline-flex;align-items:center;gap:7px;padding:6px 10px;border-radius:999px;background:rgba(10,15,36,.86);color:#FFFFFF;font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace;font-size:13px;font-weight:500;letter-spacing:.03em;text-transform:uppercase;white-space:nowrap}
.vs .capv{position:absolute;left:10px;right:10px;top:48px;z-index:2;margin:0;padding:9px 12px;border-radius:14px;background:rgba(10,15,36,.84);color:#FFFFFF;font-size:15px;font-weight:600;line-height:1.35}
.vs .repv{position:absolute;left:10px;right:10px;top:48px;z-index:3;display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:14px;background:#FFFFFF;color:#0E1430;box-shadow:0 10px 24px rgba(10,15,36,.3);animation:vRepIn .45s ease-out both}
.vs .stampv{position:absolute;left:50%;top:46%;z-index:2;padding:3px;border:2.5px solid #FF4A1C;border-radius:8px;background:rgba(255,255,255,.96);color:#B02A08;font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace;text-align:center;opacity:0;animation:vStamp 24s linear infinite}
.vsw .ctl{display:flex;align-items:center;gap:8px;height:52px;padding:0 14px 0 4px;background:#0A0F24;color:#FFFFFF}
.vsw .vtag{flex:0 0 auto;font-size:13px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:#AEB5D8}
.vsw .vbtn{width:44px;height:44px;flex:0 0 44px;border-radius:50%;border:0;background:transparent;color:#FFFFFF;display:grid;place-items:center;cursor:pointer;padding:0}
.vsw .vtrack{position:relative;flex:1;min-width:0;height:44px;display:flex;align-items:center}
.vsw .vtrack input{-webkit-appearance:none;appearance:none;width:100%;height:44px;margin:0;background:transparent;cursor:pointer}
.vsw .vtrack input::-webkit-slider-runnable-track{height:4px;border-radius:4px;background:rgba(255,255,255,.38)}
.vsw .vtrack input::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:18px;height:18px;margin-top:-7px;border-radius:50%;background:#FF4A1C;border:2px solid #FFFFFF;box-shadow:0 2px 6px rgba(0,0,0,.3)}
.vsw .vtrack input::-moz-range-track{height:4px;border-radius:4px;background:rgba(255,255,255,.38)}
.vsw .vtrack input::-moz-range-thumb{width:14px;height:14px;border-radius:50%;background:#FF4A1C;border:2px solid #FFFFFF}
.vsw .vtrack input:focus-visible{outline:3px solid #FF6B42;outline-offset:-2px;border-radius:999px}
.vsw .vtick{position:absolute;top:50%;width:6px;height:6px;margin:-3px 0 0 -3px;border-radius:50%;background:#FFFFFF;pointer-events:none}
.vs .cam{transform-box:view-box;transform-origin:0 0;animation:vCam 24s linear infinite}
.vs .truck{animation:vTruck 24s linear infinite}
.vs .tech{animation:vTech 24s linear infinite}
.vs .face{transform-box:fill-box;transform-origin:9px 0;animation:vFace 24s linear infinite}
.vs .leg1,.vs .leg2{transform-box:fill-box;transform-origin:top center;animation:vLeg .45s ease-in-out infinite alternate}
.vs .leg2{animation-direction:alternate-reverse}
.vs .gate{transform-box:fill-box;transform-origin:left center;animation:vGate 24s linear infinite}
.vs .dogw{animation:vDog 24s linear infinite}
.vs .rr{opacity:0;animation:vRR 24s linear infinite}
.vs .rrleg{transform-box:fill-box;transform-origin:top center;animation:vRRleg .12s steps(2) infinite}
.vs .pile,.vs .mist,.vs .spark,.vs .ring{transform-box:fill-box;transform-origin:center}
.vs .p1{animation:vP1 24s linear infinite}.vs .p2{animation:vP2 24s linear infinite}.vs .p3{animation:vP3 24s linear infinite}.vs .p4{animation:vP4 24s linear infinite}
.vs .p5{animation:vP5 24s linear infinite}.vs .p6{animation:vP6 24s linear infinite}.vs .p7{animation:vP7 24s linear infinite}.vs .p8{animation:vP8 24s linear infinite}
.vs .mist{opacity:0}.vs .m1{animation:vM1 24s linear infinite}.vs .m2{animation:vM2 24s linear infinite}.vs .m3{animation:vM3 24s linear infinite}.vs .m4{animation:vM4 24s linear infinite}
.vs .spark{opacity:0}.vs .k1{animation:vK1 24s linear infinite}.vs .k2{animation:vK2 24s linear infinite}.vs .k3{animation:vK3 24s linear infinite}
.vs .flash{opacity:0;animation:vFlash 24s linear infinite}
.vs .tdot{animation:vTdot 24s linear infinite}
.vs .ring{animation:vRing 1.6s ease-out infinite}
.vs.paused *{animation-play-state:paused !important}
@keyframes vCam{0%{transform:translate(20px,0) scale(1);animation-timing-function:cubic-bezier(.25,.6,.3,1)}13.333%{transform:translate(-330px,0) scale(1)}24.167%{transform:translate(-330px,0) scale(1);animation-timing-function:ease-in-out}27.5%{transform:translate(-981px,-117px) scale(1.8)}73.333%{transform:translate(-981px,-117px) scale(1.8);animation-timing-function:ease-in-out}77.5%{transform:translate(-602px,-87px) scale(1.4)}92.5%{transform:translate(-602px,-87px) scale(1.4);animation-timing-function:ease-in-out}100%{transform:translate(-480px,0) scale(1)}}
@keyframes vTruck{0%{transform:translateX(-120px);animation-timing-function:cubic-bezier(.25,.6,.3,1)}13.333%{transform:translateX(440px)}93.333%{transform:translateX(440px);animation-timing-function:cubic-bezier(.6,0,.9,.5)}100%{transform:translateX(900px)}}
@keyframes vTech{0%,14%{transform:translate(500px,190px);opacity:0}14.167%{transform:translate(500px,190px);opacity:1}20.833%{transform:translate(557px,184px)}24.167%{transform:translate(557px,184px)}25.5%{transform:translate(557px,170px)}27.5%{transform:translate(585px,156px)}35.833%{transform:translate(745px,156px)}36.667%{transform:translate(745px,148px)}45%{transform:translate(585px,148px)}45.833%{transform:translate(585px,140px)}54.167%{transform:translate(745px,140px)}55%{transform:translate(745px,132px)}60.833%{transform:translate(660px,132px)}61.667%{transform:translate(660px,132px)}65.833%{transform:translate(700px,146px)}72.5%{transform:translate(610px,156px)}74.167%{transform:translate(585px,160px)}76.667%{transform:translate(557px,170px)}78.333%{transform:translate(557px,184px)}84.167%{transform:translate(557px,184px)}90.833%{transform:translate(500px,190px);opacity:1}91.667%,100%{transform:translate(500px,190px);opacity:0}}
@keyframes vFace{0%,35.6%{transform:scaleX(1)}36.4%,45%{transform:scaleX(-1)}45.8%,54.2%{transform:scaleX(1)}55%,61.4%{transform:scaleX(-1)}62%,65.6%{transform:scaleX(1)}66.2%,100%{transform:scaleX(-1)}}
@keyframes vLeg{from{transform:rotate(-16deg)}to{transform:rotate(16deg)}}
@keyframes vGate{0%,22.5%{transform:scaleX(1)}24.167%,27.5%{transform:scaleX(.18)}29.167%,75%{transform:scaleX(1)}76.667%,78.333%{transform:scaleX(.18)}80%,80.417%{transform:scaleX(1)}81%{transform:scaleX(1) translateX(1.4px)}81.6%{transform:scaleX(1) translateX(-1.4px)}82.083%,100%{transform:scaleX(1)}}
@keyframes vDog{0%,16%{transform:translateY(14px)}18%,93%{transform:translateY(0)}95%,100%{transform:translateY(14px)}}
@keyframes vRR{0%,2%{transform:translate(430px,188px);opacity:0}2.5%{transform:translate(430px,188px);opacity:1}9.2%{transform:translate(110px,188px);opacity:1}9.6%,100%{transform:translate(90px,188px);opacity:0}}
@keyframes vRRleg{from{transform:scaleX(1)}to{transform:scaleX(-1)}}
@keyframes vP1{0%{opacity:0;transform:scale(.4)}2%,28.5%{opacity:1;transform:scale(1)}29.5%,100%{opacity:0;transform:scale(.15)}}
@keyframes vP2{0%{opacity:0;transform:scale(.4)}2%,32.92%{opacity:1;transform:scale(1)}33.92%,100%{opacity:0;transform:scale(.15)}}
@keyframes vP3{0%{opacity:0;transform:scale(.4)}2%,36.88%{opacity:1;transform:scale(1)}37.88%,100%{opacity:0;transform:scale(.15)}}
@keyframes vP4{0%{opacity:0;transform:scale(.4)}2%,41.31%{opacity:1;transform:scale(1)}42.31%,100%{opacity:0;transform:scale(.15)}}
@keyframes vP5{0%{opacity:0;transform:scale(.4)}2%,46.05%{opacity:1;transform:scale(1)}47.05%,100%{opacity:0;transform:scale(.15)}}
@keyframes vP6{0%{opacity:0;transform:scale(.4)}2%,50.48%{opacity:1;transform:scale(1)}51.48%,100%{opacity:0;transform:scale(.15)}}
@keyframes vP7{0%{opacity:0;transform:scale(.4)}2%,55.39%{opacity:1;transform:scale(1)}56.39%,100%{opacity:0;transform:scale(.15)}}
@keyframes vP8{0%{opacity:0;transform:scale(.4)}2%,59.16%{opacity:1;transform:scale(1)}60.16%,100%{opacity:0;transform:scale(.15)}}
@keyframes vM1{0%,63.2%{opacity:0;transform:scale(.3)}63.4%{opacity:.85;transform:scale(.35)}67.5%,100%{opacity:0;transform:scale(2.6)}}
@keyframes vM2{0%,66.1%{opacity:0;transform:scale(.3)}66.3%{opacity:.85;transform:scale(.35)}70.4%,100%{opacity:0;transform:scale(2.6)}}
@keyframes vM3{0%,69%{opacity:0;transform:scale(.3)}69.2%{opacity:.85;transform:scale(.35)}73.3%,100%{opacity:0;transform:scale(2.6)}}
@keyframes vM4{0%,71.9%{opacity:0;transform:scale(.3)}72.1%{opacity:.85;transform:scale(.35)}76.2%,100%{opacity:0;transform:scale(2.6)}}
@keyframes vK1{0%,73%{opacity:0;transform:scale(.2)}74.5%{opacity:1;transform:scale(1)}78%,100%{opacity:0;transform:scale(.6)}}
@keyframes vK2{0%,74%{opacity:0;transform:scale(.2)}75.5%{opacity:1;transform:scale(1)}79%,100%{opacity:0;transform:scale(.6)}}
@keyframes vK3{0%,75%{opacity:0;transform:scale(.2)}76.5%{opacity:1;transform:scale(1)}80%,100%{opacity:0;transform:scale(.6)}}
@keyframes vFlash{0%,82.4%{opacity:0}82.6%{opacity:.85}84.2%,100%{opacity:0}}
@keyframes vTdot{0%,14%{opacity:1}14.5%,91.6%{opacity:0}92%,100%{opacity:1}}
@keyframes vRing{0%{transform:scale(1);opacity:.9}100%{transform:scale(3.2);opacity:0}}
@keyframes vStamp{0%,83%{opacity:0;transform:scale(1.7) rotate(-10deg)}84%,97.5%{opacity:1;transform:scale(1) rotate(-4deg)}99%,100%{opacity:0;transform:scale(1) rotate(-4deg)}}
@keyframes vRepIn{from{opacity:0;transform:translateY(-10px)}to{opacity:1;transform:none}}
.uline{position:relative;white-space:nowrap}
.uline svg{position:absolute;left:-2%;bottom:-.14em;width:104%;height:.32em;overflow:visible}
.uline path{fill:none;stroke:#FF4A1C;stroke-width:4;stroke-linecap:round;stroke-dasharray:320;stroke-dashoffset:320;animation:apwDraw 1s .5s ease-out forwards}
@keyframes apwDraw{to{stroke-dashoffset:0}}
.sticker{position:absolute;z-index:2;display:grid;place-items:center;width:78px;height:78px;border-radius:50%;background:#FF4A1C;color:#0E1430;text-align:center;font-size:13px;font-weight:800;line-height:1.05;text-transform:uppercase;letter-spacing:.02em;box-shadow:0 6px 14px rgba(10,15,36,.22);transform:rotate(9deg);pointer-events:none}
.sticker::after{content:"";position:absolute;inset:5px;border-radius:50%;border:1.5px dashed rgba(14,20,48,.55)}
.route{position:relative;list-style:none;margin:26px 0 0;padding:0}
.route::before{content:"";position:absolute;left:75px;top:10px;bottom:10px;width:2px;background:repeating-linear-gradient(to bottom,#FF4A1C 0 7px,transparent 7px 13px)}
.stop{display:grid;grid-template-columns:64px 24px minmax(0,1fr);align-items:start;padding-bottom:28px}
.stop:last-child{padding-bottom:0}
.stime{padding-top:2px;text-align:right;font-size:13px;font-weight:600;color:var(--accent-text);white-space:nowrap}
.snode{justify-self:center;width:14px;height:14px;margin-top:3px;border-radius:50%;border:3px solid #FF4A1C;position:relative;z-index:1}
.sbody{min-width:0;padding-left:4px}
.sbody h3{margin:0;font-size:19px;font-weight:800;letter-spacing:-.025em;line-height:1.15;color:var(--ink)}
.sbody p{margin:6px 0 0;font-size:16px;line-height:1.5;color:var(--ink2)}
.rdot{position:absolute;left:69px;z-index:2;width:16px;height:16px;margin-top:-8px;border-radius:50%;background:#FF4A1C;box-shadow:0 0 0 3px var(--bg2);transition:top .25s ease-out}
.rdot::after{content:"";position:absolute;inset:-3px;border-radius:50%;border:2px solid #FF4A1C;animation:apwRing 1.8s ease-out infinite}
@keyframes apwRing{0%{transform:scale(1);opacity:.9}100%{transform:scale(2.4);opacity:0}}
.bub{display:inline-block;max-width:100%;margin-top:10px;padding:11px 14px;border-radius:18px 18px 18px 6px;background:var(--card);border:1px solid var(--line);font-size:15px;line-height:1.45;color:var(--ink)}
.minimap{position:relative;margin-top:10px;border-radius:16px;overflow:hidden;border:1px solid var(--line);background:#F3E7D2;aspect-ratio:2/1}
.minimap svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.mmdot{animation:mmDrive 6s ease-in-out infinite}
@keyframes mmDrive{0%{transform:translate(18px,92px)}30%{transform:translate(118px,92px)}55%{transform:translate(118px,40px)}80%,100%{transform:translate(196px,40px)}}
.dogrow{flex:1;min-width:0;display:flex;flex-wrap:wrap;justify-content:center;gap:2px;min-height:44px}
.dogf{display:block;width:40px;height:40px;animation:dogPop .4s cubic-bezier(.3,1.6,.5,1) both}
@keyframes dogPop{from{transform:scale(.2) rotate(-20deg);opacity:0}to{transform:none;opacity:1}}
.cal{display:grid;grid-template-columns:repeat(7,9px);gap:3px}
.cal span{display:block;width:9px;height:9px;border-radius:3px}
.qa{margin-top:10px}
.qa summary{display:flex;justify-content:flex-end}
.qb{margin:0;font-family:inherit;letter-spacing:normal;max-width:86%;padding:12px 16px;border-radius:20px 20px 6px 20px;background:var(--ink);color:var(--bg);font-size:16px;font-weight:600;line-height:1.4}
.qa[open] .qb{background:#FF4A1C;color:#0E1430}
.ab{display:flex;gap:8px;align-items:flex-end;margin-top:8px}
.ab img{width:28px;height:28px;flex:0 0 28px;display:block}
.ab p{margin:0;max-width:86%;padding:12px 16px;border-radius:20px 20px 20px 6px;background:var(--card);border:1px solid var(--line);font-size:16px;line-height:1.5;color:var(--ink)}
.rcpt{position:relative;margin-top:30px;padding:24px 20px 26px;background:#FFFFFF;color:#0E1430}
.rcpt::before,.rcpt::after{content:"";position:absolute;left:0;right:0;height:10px;background-size:14px 10px;background-repeat:repeat-x}
.rcpt::before{top:-10px;background-image:linear-gradient(135deg,transparent 7px,#FFFFFF 7px),linear-gradient(225deg,transparent 7px,#FFFFFF 7px)}
.rcpt::after{bottom:-10px;background-image:linear-gradient(45deg,transparent 7px,#FFFFFF 7px),linear-gradient(315deg,transparent 7px,#FFFFFF 7px)}
.rrow{display:flex;align-items:baseline;gap:8px;padding:9px 0;font-size:16px;font-weight:600}
.rrow i{flex:1;min-width:16px;border-bottom:2px dotted #C9C2B3;transform:translateY(-4px)}
.rrow b{font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace;font-size:14px;font-weight:600;color:#B02A08;white-space:nowrap}
.ph{display:grid;place-items:center;text-align:center;border:1.6px dashed var(--field);background:var(--bg3);color:var(--mute);font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace;font-size:13px;line-height:1.2}
@media (prefers-reduced-motion:reduce){.uline path{animation:none;stroke-dashoffset:0}.rdot::after,.mmdot,.dogf{animation:none}}
.routew{position:relative;margin-top:26px}.route{margin:0}
.map{position:relative;overflow:hidden;margin:22px -20px 0;aspect-ratio:384/316;background:#F3E7D2;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.map svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.mland{fill:#F3E7D2}.dark .mland{fill:#141D3D}
.mmtn{fill:#D3C1AD}.dark .mmtn{fill:#2D2A4A}
.mridge{fill:none;stroke:#B39E88;stroke-width:1.3;stroke-linecap:round;stroke-linejoin:round}.dark .mridge{stroke:#463F6B}
.mbase{fill:#E4DCCD}.dark .mbase{fill:#1B2449}
.mrun{fill:none;stroke:#CFC5B4;stroke-width:4;stroke-linecap:round}.dark .mrun{stroke:#2C3767}
.mart{fill:none;stroke:#FFFFFF;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.dark .mart{stroke:#28346A}
.mcanal{fill:none;stroke:#8CC4E6;stroke-width:1.4;stroke-linejoin:round}.dark .mcanal{stroke:#3D6E95}
.mriver{fill:none;stroke:#8DBEE0;stroke-width:2.2;stroke-dasharray:1 4;stroke-linecap:round}
.mzipf{fill:rgba(255,74,28,.07);pointer-events:none}.dark .mzipf{fill:rgba(255,74,28,.10)}
.mzipl{fill:none;stroke:#FF4A1C;stroke-width:1.4;stroke-dasharray:5 3;stroke-linejoin:round;opacity:.85;pointer-events:none}
.mzipt{font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace;font-size:10px;font-weight:600;letter-spacing:.04em;fill:#B02A08;paint-order:stroke;stroke:#F3E7D2;stroke-width:3px;stroke-linejoin:round;pointer-events:none}.dark .mzipt{fill:#FF8A66;stroke:#141D3D}
.mplc{cursor:pointer;transition:fill .25s ease}
.mfwy0{fill:none;stroke:#D99A3A;stroke-width:6;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.mfwy{fill:none;stroke:#F7C66A;stroke-width:3.8;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.dark .mfwy0{stroke:#7A5A26}.dark .mfwy{stroke:#B98B3E}
.mnolook,.mtxt,.mplace,.mattr,.mtruck{pointer-events:none}
.mtxt{font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace;font-size:10px;font-weight:600;letter-spacing:.06em;fill:#7A6F60}.dark .mtxt{fill:#9AA2C8}
