    const extra = { week: 13, twice: 13, eow: 9 };
    return base[id] + Math.max(0, dogs - 2) * extra[id];
  }
  _per(id, dogs) {
    const visits = { week: 52 / 12, twice: 104 / 12, eow: 26 / 12 };
    return Math.round(this._price(id, dogs) / visits[id]);
  }
  _cal(id, onBand) {
    const out = [];
    for (let i = 0; i < 28; i++) {
      const d = i % 7;
      const w = Math.floor(i / 7);
      const on = id === 'week' ? d === 2 : id === 'twice' ? (d === 2 || d === 5) : (d === 2 && w % 2 === 0);
      out.push({ bg: on ? '#FF4A1C' : (onBand ? 'rgba(255,255,255,.16)' : 'var(--line)') });
    }
    return out;
  }
  _plans(onBand) {
    const s = this.state;
    const names = { week: 'Every week', twice: 'Twice a week', eow: 'Every other week' };
    return ['week', 'twice', 'eow'].map((id) => {
      const on = s.plan === id;
      return {
        id: id,
        name: names[id],
        price: '$' + this._price(id, s.dogs),
        per: 'About $' + this._per(id, s.dogs) + ' a visit',
        on: on,
        pick: () => this.setState({ plan: id }),
        aria: names[id] + ', $' + this._price(id, s.dogs) + ' a month',
        cal: this._cal(id, onBand),
        border: on ? '#FF4A1C' : (onBand ? 'rgba(255,255,255,.18)' : 'var(--field)'),
        bg: on ? 'rgba(255,74,28,.12)' : 'transparent',
        ring: on ? '#FF4A1C' : (onBand ? '#AEB5D8' : 'var(--mute)'),
        dot: on ? '#FF4A1C' : 'transparent'
      };
    });
  }
  _zipArea(zip) {
    return ({ '85326': 'buckeye', '85396': 'buckeye', '85338': 'goodyear', '85395': 'goodyear', '85340': 'litchfield', '85355': 'citrus' })[zip] || '';
  }
  _checkZip() {
    this.setState({ zipChecked: true, area: this._zipArea(this.state.zip) });
  }
  _areaVals() {
    const s = this.state;
    const areas = {
      buckeye: { name: 'Buckeye', meta: 'BUCKEYE · ZIP 85326 AND 85396' },
      verrado: { name: 'Verrado', meta: 'VERRADO · BUCKEYE · ZIP 85396' },
      citrus: { name: 'Citrus Park', meta: 'CITRUS PARK · WADDELL · ZIP 85355' },
      goodyear: { name: 'Goodyear', meta: 'GOODYEAR · ZIP 85338 AND 85395' },
      litchfield: { name: 'Litchfield Park', meta: 'LITCHFIELD PARK · ZIP 85340' }
    };
    const pin = (id) => {
      const on = s.area === id;
      return { on: on, bg: on ? 'var(--ink)' : 'var(--card)', fg: on ? 'var(--bg)' : 'var(--ink)', pick: () => this.setState({ area: id, zip: '', zipChecked: false }) };
    };
    const blob = (id) => (s.area === id ? (s.dark ? 'rgba(255,74,28,.58)' : 'rgba(255,74,28,.42)') : 'rgba(255,74,28,0)');
    const a = areas[s.area];
    const byZip = s.zipChecked && !!this._zipArea(s.zip);
    return {
      mB: pin('buckeye'), mV: pin('verrado'), mC: pin('citrus'), mG: pin('goodyear'), mL: pin('litchfield'),
      bB: blob('buckeye'), bV: blob('verrado'), bC: blob('citrus'), bG: blob('goodyear'), bL: blob('litchfield'),
      areaOn: !!a,
      areaName: byZip ? 'ZIP ' + s.zip : (a ? a.name : ''),
      areaMeta: a ? a.meta : '',
      zip: s.zip,
      onZip: (e) => this.setState({ zip: String(e.target.value || '').replace(/\D/g, '').slice(0, 5), zipChecked: false }),
      zipKey: (e) => { if (e.key === 'Enter') this._checkZip(); },
      checkZip: () => this._checkZip(),
      zipNo: s.zipChecked && s.zip.length === 5 && !this._zipArea(s.zip),
      zipShort: s.zipChecked && s.zip.length < 5
    };
  }
  _ydP() {
    return this.__ydp || (this.__ydp = [[90.6,194.3,18],[46.9,194.3,129],[74.0,139.9,61],[160.7,235.5,31],[222.8,194.4,15],[153.6,270.4,11],[86.1,140.1,138],[131.0,233.0,46],[198.2,86.0,24],[68.1,55.9,52],[188.1,223.9,119],[168.0,112.1,46],[114.5,176.4,134],[139.9,147.0,155],[54.7,143.9,87],[177.2,51.2,171],[127.6,123.2,127],[171.5,219.2,15],[131.3,177.2,174],[109.3,134.1,171],[292.8,125.2,156],[67.1,221.8,33],[153.9,256.5,127],[167.0,170.6,35],[299.4,101.2,106],[239.9,132.4,59],[97.1,96.3,59],[264.8,84.7,72],[159.3,128.4,144],[84.1,243.1,158],[241.4,148.9,174],[214.4,56.6,17],[160.5,49.6,153],[52.1,77.4,25],[217.3,37.5,53],[145.2,70.7,124],[78.2,122.2,67],[229.2,162.8,52],[189.3,60.9,139],[264.7,107.2,164],[244.4,95.9,93],[132.7,84.2,138],[339.1,276.9,61],[143.0,48.8,7],[170.9,75.3,154],[329.2,127.6,56],[304.2,184.8,0],[219.2,229.1,21],[103.0,250.0,111],[125.1,261.1,101],[242.3,61.9,40],[84.5,77.4,119],[231.6,123.2,140],[57.5,229.0,166],[243.9,74.6,49],[85.2,93.1,74],[247.5,118.3,139],[85.6,254.9,90],[233.3,265.4,132],[286.9,159.4,136],[182.7,246.2,46],[210.5,70.2,15],[184.7,172.0,27],[34.6,74.5,10],[182.5,187.9,16],[208.8,160.3,131],[123.0,160.9,122],[82.4,152.9,106],[70.7,198.7,31],[66.7,235.1,169],[116.8,74.1,119],[305.4,236.8,41],[306.5,136.5,107],[133.5,211.0,4],[169.4,206.5,98],[50.4,97.3,10],[294.7,222.8,66],[135.7,107.3,176],[281.2,104.9,4],[257.2,61.6,56],[272.9,148.2,86],[63.1,208.0,28],[101.9,71.4,79],[188.0,90.2,114],[97.5,123.2,4],[28.1,21.6,129],[100.5,153.1,114],[261.6,143.1,126],[279.5,269.1,78],[303.5,122.2,162]]);
  }
  _ydN(s) {
    return Math.max(1, s.dogs * s.ydDays * 2);
  }
  _ydVals() {
    const s = this.state;
    const n = s.ydPhase === 'idle' ? this._ydN(s) : s.ydRunN;
    const all = this._ydP();
    const shown = Math.min(n, all.length);
    const lbs = Math.max(1, Math.round(s.dogs * s.ydDays * 0.75));
    const days = s.ydDays === 1 ? '1 day' : s.ydDays + ' days';
    const steps = { enter: 'We shut the gate behind us.', rows: 'We pick up every pile, row by row.', spray: 'We spray the spots your dogs use most. It is free.', exit: 'We latch the gate and pull on it.', photo: 'We send you a photo of your latched gate.' };
    return {
      ydDays: s.ydDays,
      ydDaysLabel: days,
      ydN: n,
      ydLbs: lbs,
      ydPileWord: n === 1 ? 'pile' : 'piles',
      ydPiles: all.slice(0, shown).map((p) => ({ t: 'translate(' + p[0] + ' ' + p[1] + ') rotate(' + p[2] + ')' })),
      ydCls: 'ydw' + (s.ydPhase !== 'idle' ? (s.ydPhase === 'done' ? ' done' : ' run') : '') + (s.ydStep ? ' st-' + s.ydStep : ''),
      ydIdle: s.ydPhase === 'idle',
      ydRunning: s.ydPhase === 'run',
      ydDone: s.ydPhase === 'done',
      ydAria: s.ydPhase === 'done' ? 'The same backyard, clean, with the gate latched.' : 'A backyard from above with ' + n + ' ' + (n === 1 ? 'pile' : 'piles') + ' of dog poop.',
      ydStatus: s.ydPhase === 'done' ? 'All clean. ' + n + ' ' + (n === 1 ? 'pile' : 'piles') + ' gone, and the gate is latched.' : (steps[s.ydStep] || ('This is a yard after ' + days + ' with ' + (s.dogs === 1 ? '1 dog' : s.dogs + ' dogs') + '.')),
      ydSetDays: (e) => {
        const v = Math.max(1, Math.min(30, parseInt(e && e.target ? e.target.value : 7, 10) || 7));
        this._ydReset();
        this.setState({ ydDays: v, ydPhase: 'idle', ydStep: '' });
      },
      ydGo: () => this._ydStart(),
      ydAgain: () => {
        this._ydReset();
        this.setState({ ydPhase: 'idle', ydStep: '' });
      }
    };
  }
  _ydEls() {
    const root = this.__root || document;
    return {
      sc: root.querySelector('#yd-sc'),
      trail: root.querySelector('#yd-trail'),
      clock: root.querySelector('#yd-clock'),
      piles: Array.prototype.slice.call(root.querySelectorAll('#yd-piles .ydp'))
    };
  }
  _ydReset() {
    if (this._ydRaf) cancelAnimationFrame(this._ydRaf);
    this._ydRaf = 0;
    if (typeof document === 'undefined') return;
    const e = this._ydEls();
    e.piles.forEach((p) => p.classList.remove('gone'));
    if (e.trail) e.trail.setAttribute('stroke-dashoffset', '1');
    if (e.sc) e.sc.setAttribute('transform', 'translate(372 68)');
    if (e.clock) e.clock.textContent = '10:00 AM';
  }
  _ydStop() {
    if (this._ydRaf) cancelAnimationFrame(this._ydRaf);
    this._ydRaf = 0;
  }
  _ydStart() {
